import itertools

def solve_for_m(m, n):
    # Generate all possible distributions of n pebbles into m boxes (all x_i >= 1)
    def get_distributions(m, n):
        if m == 1:
            yield (n,)
            return
        for i in range(1, n - m + 2):
            for rest in get_distributions(m - 1, n - i):
                yield (i,) + rest

    distributions = list(get_distributions(m, n))
    dist_to_idx = {d: i for i, d in enumerate(distributions)}
    num_dist = len(distributions)

    # is_winning[i] = True if Alice can win from distribution i
    # Initially, all distributions are potentially winning
    is_winning = [True] * num_dist

    while True:
        changed = False
        for i in range(num_dist):
            if not is_winning[i]:
                continue

            # Distribution X is winning if for all k, Alice has a choice c such that X_{k,c} is winning
            for k in range(1, m):
                # Bob picks k (boxes are B_1...B_k and B_{k+1}...B_m)
                # Alice's choices:
                # c = 1: boxes 1..k get +1, boxes k+1..m get -1
                # c = -1: boxes 1..k get -1, boxes k+1..m get +1

                # Case c = 1
                X = distributions[i]
                X_plus = list(X)
                for j in range(k): X_plus[j] += 1
                for j in range(k, m): X_plus[j] -= 1
                tuple_plus = tuple(X_plus)
                win_plus = tuple_plus in dist_to_idx and is_winning[dist_to_idx[tuple_plus]]

                # Case c = -1
                X_minus = list(X)
                for j in range(k): X_minus[j] -= 1
                for j in range(k, m): X_minus[j] += 1
                tuple_minus = tuple(X_minus)
                win_minus = tuple_minus in dist_to_idx and is_winning[dist_to_idx[tuple_minus]]

                if not (win_plus or win_minus):
                    is_winning[i] = False
                    changed = True
                    break
        if not changed:
            break

    return any(is_winning)

for m in range(2, 6):
    for n in range(m, 100):
        if solve_for_m(m, n):
            print(f"m={m}, min n={n}")
            break

