def solve_for_m_L(m, n, L):
    # Only consider distributions where x_1 + x_m = L
    def get_distributions(m, n, L):
        # x_1 + x_m = L, x_i >= 1
        # x_2 + ... + x_{m-1} = n - L
        # x_1 can be from 1 to L-1
        res = []
        for x1 in range(1, L):
            xm = L - x1
            # Distribute n-L into m-2 boxes
            if m == 2:
                if n == L:
                    res.append((x1, xm))
                continue

            def get_rest(m_rest, n_rest):
                if m_rest == 1:
                    yield (n_rest,)
                    return
                for i in range(1, n_rest - m_rest + 2):
                    for rest in get_rest(m_rest - 1, n_rest - i):
                        yield (i,) + rest

            for rest in get_rest(m - 2, n - L):
                res.append((x1,) + rest + (xm,))
        return res

    distributions = get_distributions(m, n, L)
    dist_to_idx = {d: i for i, d in enumerate(distributions)}
    num_dist = len(distributions)
    is_winning = [True] * num_dist
    while True:
        changed = False
        for i in range(num_dist):
            if not is_winning[i]: continue
            for k in range(1, m):
                X = distributions[i]
                X_plus = list(X)
                for j in range(k): X_plus[j] += 1
                for j in range(k, m): X_plus[j] -= 1
                tuple_plus = tuple(X_plus)
                win_plus = tuple_plus in dist_to_idx and is_winning[dist_to_idx[tuple_plus]]
                X_minus = list(X)
                for j in range(k): X_minus[j] -= 1
                for j in range(k, m): X_minus[j] += 1
                tuple_minus = tuple(X_minus)
                win_minus = tuple_minus in dist_to_idx and is_winning[dist_to_idx[tuple_minus]]
                if not (win_plus or win_minus):
                    is_winning[i] = False
                    changed = True
                    break
        if not changed: break
    return any(is_winning)

